from pathlib import Path
from seo_metadata import metadata
from PIL import Image,ImageOps
import json,html,re,unicodedata,datetime,shutil,subprocess
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'new-design';AS=OUT/'assets';AS.mkdir(exist_ok=True)
def esc(s):return html.escape(str(s),quote=True)
def slug(s):return re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()).strip('-')
def derivative(src,dst,size):
 if dst.exists():return
 im=ImageOps.exif_transpose(Image.open(src)).convert('RGB');im.thumbnail(size);im.save(dst,'WEBP',quality=88)
art=[]
for p in sorted(Path('/Users/manuariza/Downloads/Antonio Art').glob('*.jpg')):
 title=p.stem.capitalize();s=slug(title);im=ImageOps.exif_transpose(Image.open(p));w,h=im.size
 for width in [700,1800,2600]:derivative(p,AS/f'{s}-{width}.webp',(width,width))
 edge=int(min(w,h)*.42);cx=int(w*.52);cy=int(h*.48);detail=im.crop((cx-edge//2,cy-edge//2,cx+edge//2,cy+edge//2));detail.thumbnail((1200,1200));detail.save(AS/f'{s}-detail.webp',quality=91)
 art.append(dict(title=title,slug=s,width=w,height=h))
for n in [2,3,4]:derivative(ROOT/f'img/bg-img/{n}.jpg',AS/f'studio-{n}.webp',(1800,1800))
posts=list({p['code']:p for p in json.load(open(ROOT/'reports/content-archive/instagram.json'))}.values())
for p in posts:
 for m in p.get('media',[]):
  if m.get('file') and m['type']=='video':
   poster=AS/'restoration'/(m['file']+'.poster.jpg')
   if not poster.exists():subprocess.run(['/opt/homebrew/bin/ffmpeg','-loglevel','error','-ss','0.1','-i',str(AS/'restoration'/m['file']),'-frames:v','1','-vf','scale=900:-2','-y',str(poster)],check=True)

by={p['code']:p for p in posts}
# Editorial summaries are limited to interventions explicitly described by the studio.
case_specs=[
('virgen-de-tomalos','Virgen de Tómalos','Pintura · 1756',['CpUxKd9j7q6'],'Un lienzo con siglos de historia','La suciedad superficial, las deformaciones del lienzo y numerosas roturas convivían con antiguas reparaciones en el reverso. La documentación muestra el estado de la obra, sus detalles y su presentación tras la intervención.','Óleo sobre lienzo · 200 × 140 cm','La limpieza de depósitos biológicos se realizó mecánicamente. Las deformaciones se trataron con presión y calor. El estudio advierte que algunas marcas de corrosión en la pintura son irreversibles.'),
('retrato-de-hombre','Retrato de hombre','Fotografía coloreada · c. 1880',['CiHhxW7j5Tt'],'La fragilidad de una imagen','Una fotografía sobre papel adherida a lienzo y coloreada al óleo. El delicado soporte y las pérdidas de pintura requerían estabilizar la obra antes de su presentación.','Anónimo español · 80 × 60 cm','Consolidación de la pintura sobre el papel fotográfico, limpieza de suciedad superficial y reintegración cromática de las pérdidas.'),
('arcangel-san-rafael','Arcángel San Rafael','Escultura · Siglo XVIII',['Cb8IjyHD99i'],'Conservar la policromía','Una talla de arte popular con pérdidas de policromía y zonas sin adherencia al soporte. La intervención distingue las carnaduras de los ropajes y las alas.','Anónimo español · Madera policromada y dorada · 80 cm','Consolidación y limpieza superficial. Las carnaduras se reintegraron con estuco y color; en los ropajes y alas se aplicó una tinta plana neutra, sin estucar las faltas.'),
('retrato-de-senora','Retrato de señora','Pintura · 1906',['Cbuvs9dq4tP'],'Recuperar la lectura del retrato','Un retrato de Gonzalo Bilbao Martínez. El barniz envejecido y la suciedad alteraban la percepción de los colores, mientras que pintura y soporte conservaban su estabilidad.','Gonzalo Bilbao · Óleo sobre lienzo · 100 × 80 cm','Eliminación del barniz viejo y amarillento y de la suciedad de polución. La comparación original se conserva íntegra.'),
('el-cid','El Cid parte al destierro','Pintura · 1877',['CY015pbjnBi','CbZkskVjtue'],'La estructura de una gran pintura','Julio Cebrián Mezquita representa la despedida del Cid en San Pedro de Cardeña. El lienzo llegó con graves daños en los bordes y pérdida de sujeción al bastidor.','Julio Cebrián Mezquita · Óleo sobre lienzo · 190 × 225 cm','La documentación describe la colocación de bordes de refuerzo y el tratamiento previsto para roturas, pérdidas y barnices oxidados. Estas imágenes muestran un proceso en curso; no acreditan un resultado final.'),
('san-juan-evangelista','Guirnalda con San Juan Evangelista','Pintura · Siglo XVII',['CbFjWUWKX_S'],'El color entre las flores','Una composición de guirnalda floral alrededor de la efigie del santo. Las restauraciones antiguas y los barnices oxidados alteraban su lectura.','Anónimo español · Óleo sobre lienzo · 80 × 60 cm','Retirada de barnices oxidados y reintegración cromática en las zonas donde se había perdido pintura original.'),
('santiago-clavijo','Santiago en la batalla de Clavijo','Pintura · Primera mitad del siglo XVIII',['CUIHAQkjtJg'],'Una pintura, varias capas de historia','Una pintura anónima española cuyo proceso de conservación se documenta mediante una comparación de estados.','Anónimo español · Óleo sobre lienzo · 100 × 80 cm','Sentado de los estratos pictóricos y eliminación de barnices antiguos y suciedad superficial.'),
('retrato-de-nino','Retrato de niño','Pintura · Mediados del siglo XIX',['CTfZqL_DOvh'],'Devolver estabilidad a la pintura','Los cambios de humedad y temperatura, junto con la deficiente fijación al bastidor, habían provocado el desprendimiento de las capas pictóricas.','Anónimo español · Siglo XIX','Consolidación de los estratos pictóricos, recuperación de su adherencia y aplanado del craquelado. Tras ajustar la tensión de la tela, se inició la limpieza del barniz oxidado.'),
('la-piedad','La Piedad','Escultura · Siglos XVII–XVIII',['CS_doW0j8g-'],'Materia, volumen y policromía','Un conjunto en madera de nogal con fendas, desprendimientos, repintes y pérdidas de volumen. Cristo es una talla completa; la Virgen es una imagen de vestir.','Madera de nogal policromada · Siglos XVII–XVIII','Consolidación de madera y policromía, retirada selectiva de repintes, limpieza, reconstrucción de dedos perdidos, estucado, reintegración cromática y barnizado protector. Se conservó el repinte azul del paño de pureza.'),
('pasmado-del-barniz','El pasmado del barniz','Proceso · Vídeo',['CQL9b-wK3bQ'],'Cuando el barniz oculta la pintura','Los halos blanquecinos del barniz pueden velar la imagen. Este vídeo documenta la eliminación de un barniz pasmado en una obra expuesta a un ambiente muy húmedo.','Vídeo de proceso · Reproducción original a 32×','La publicación explica la relación entre humedad y pasmado. La secuencia está acelerada: no representa la duración real del tratamiento.'),
('vida-en-el-estudio','Vida en el estudio','Cuaderno · Enero de 2022',['CYbZ9K4DM0h'],'Un lugar para mirar despacio','Una vista del taller compartida por Antonio al comienzo de 2022, entre obras y nuevos proyectos.','Archivo del estudio','Esta fotografía documenta el espacio de trabajo en la fecha de la publicación.')]
cases=[]
case_specs += [
('calvario-anchieta','Calvario de Juan de Anchieta','Escultura · Siglo XVI',['CLZYraTD__V','CGuPNmkDY5m'],'Una mirada al Renacimiento','Tres tallas de madera dorada y policromada: Cristo, la Virgen y San Juan Evangelista. Las publicaciones del estudio atribuyen el conjunto a Juan de Anchieta.','Juan de Anchieta · Madera de nogal dorada y policromada','En la Dolorosa, la madera estaba estable, pero varias capas alteraban la policromía: barniz de resina vegetal, un rebarnizado de goma laca y cera superficial. La restauración consistió en retirar esas capas. La documentación incluye el conjunto terminado, comparativas y un vídeo de limpieza.'),
('arcangel-san-miguel','El Arcángel San Miguel','Pintura · Siglo XVII',['CIocEuTjTvv'],'La claridad del color','Una película de barniz amarillento impedía apreciar los colores de una pintura cuyo soporte y estratos pictóricos se encontraban en buen estado.','Círculo de los Rizi · Óleo sobre lienzo · 200 × 130 cm','Retirada de los viejos barnices oxidados.'),
('retrato-balaca','Retrato de niño, de Balaca','Pintura · Hacia 1865',['CBOGTUyDKiR'],'Un retrato sobre caoba','Una pequeña pintura de Ricardo Balaca con un barniz grueso y amarillento, además de depósitos de suciedad superficial.','Ricardo Balaca · Óleo sobre caoba · 35 × 25 cm','Retirada del barniz envejecido y limpieza de suciedad superficial.'),
('huida-a-egipto','La Huida a Egipto','Pintura · 1862',['CAvZbNYDLKG'],'Recuperar una escena','Francisco Díaz Carreño presentó esta pintura en la Exposición Nacional de 1862, según la documentación del estudio.','Francisco Díaz Carreño · Óleo sobre lienzo · 120 × 97 cm','Limpieza de depósitos de polvo, humo y contaminación, y retirada de un barniz oxidado y amarilleado.'),
('inmaculada-concepcion','Inmaculada Concepción','Pintura · Siglo XVIII',['CEL9SM_DliU'],'Leer bajo el barniz','Una pintura anónima con depósitos de suciedad, barniz oxidado y repintes posteriores a su realización.','Anónimo · Óleo sobre lienzo · 200 × 140 cm','Limpieza de la superficie y retirada de repintes documentados en la publicación del estudio.')]
case_specs.append(('florero-baudesson','Florero, copia de Baudesson','Pintura y marco · Siglo XVIII',['B2jGiSDjazY'],'La profundidad de las flores','Un florero anónimo francés, copia de Nicolas Baudesson, llegó con el lienzo destensado, roturas y una película pictórica frágil. La suciedad y un barniz espeso y amarillento ocultaban la luz y el color. La intervención también recuperó la lectura del dorado del marco.','Anónimo francés · Copia de Nicolas Baudesson · Siglo XVIII','Consolidación de la pintura con papel japonés, cola natural, calor y presión; colocación de parches; limpieza de suciedad y barniz envejecido; estucado y reintegración de pérdidas; barnizado final. En el marco se retiró la purpurina oxidada que cubría el dorado antiguo.'))
for s,t,k,ids,h,intro,facts,process in case_specs:
 if not all(id in by for id in ids):continue
 media=[m for id in ids for m in by[id].get('media',[]) if m.get('status')=='downloaded'];cases.append(dict(slug=s,title=t,kind=k,ids=ids,heading=h,intro=intro,facts=facts,process=process,media=media))
BASE='/new-design/'
def link(path):return BASE+path
mark='<img class="brand-emblem" src="/new-design/assets/brand/demoreto-emblem.webp" width="66" height="66" alt="" aria-hidden="true">'
