studio=f'<section class="page-title"><span class="eyebrow">III / EL ESTUDIO</span><h1>Antonio G. Ariza.<br><em>Una mirada, tres prácticas.</em></h1></section><section class="studio-spread biography"><div class="studio-copy"><span class="eyebrow">RESTAURACIÓN · INVESTIGACIÓN · PINTURA</span><h2>El conocimiento<br>y las manos.</h2><p>Antonio G. Ariza es licenciado en Historia del Arte por la Universidad Complutense de Madrid y restaurador formado en la Escuela Superior de Conservación y Restauración de la Comunidad de Madrid.</p><p>Compagina la restauración con la investigación, con especial atención a la pintura española del siglo XIX. Su práctica como pintor abre otra relación con el color y con la superficie.</p><a class="action" href="{BASE}obra/">{{ CONOCER SU OBRA }}</a></div>{img("studio-3.webp","Trabajo de restauración en el estudio",eager=True)}</section><section class="wide-photo">{img("studio-2.webp","Vista del taller DeMoreto")}<p>El taller · Archivo del estudio</p></section><section class="practice"><span class="eyebrow">EL TRABAJO DEL ESTUDIO</span><div><h2>Cada obra requiere<br><em>su propia atención.</em></h2><p>La documentación de las intervenciones permite conocer el estado de las piezas, los materiales afectados y las decisiones del proceso.</p><div class="practice-row"><span>01</span><h3>Pintura</h3><p>Conservación de soportes y estratos pictóricos, limpieza y reintegración.</p></div><div class="practice-row"><span>02</span><h3>Escultura</h3><p>Consolidación de madera, conservación de policromías y tratamiento de pérdidas.</p></div><div class="practice-row"><span>03</span><h3>Investigación</h3><p>Historia del arte y estudio de la pintura española del siglo XIX.</p></div></div></section>'
page('estudio','El estudio',studio,'studio')
contact=f'<section class="page-title"><span class="eyebrow">IV / CONTACTO</span><h1>Todo empieza<br><em>con una conversación.</em></h1></section><section class="contact-layout contact-direct"><div><span class="eyebrow">ESCRIBA AL ESTUDIO</span><h2>Hablemos de su obra.</h2><p>Para consultar una restauración o conocer la obra de Antonio, escríbanos directamente.</p><a class="contact-email" id="contact-email" href="mailto:agariza@gmail.com">agariza@gmail.com ↗</a><div class="contact-actions"><a class="action" id="email-action" href="mailto:agariza@gmail.com">{{ ESCRIBIR UN CORREO ↗ }}</a><button class="action" type="button" id="copy-email">{{ COPIAR DIRECCIÓN }}</button></div><p class="copy-status" id="copy-status" role="status"></p><p class="contact-help">Puede utilizar su aplicación de correo o copiar la dirección en su correo web.</p><p class="enquiry-context" id="enquiry-context" hidden></p><dl><div><dt>Estudio</dt><dd>Madrid · Visitas con cita previa</dd></div><div><dt>Archivo y actualidad</dt><dd><a href="https://www.instagram.com/moreto_restauracion/">@moreto_restauracion ↗</a></dd></div></dl></div><aside class="contact-guidance"><span class="eyebrow">PARA EMPEZAR</span><h2>Una primera<br><em>mirada.</em></h2><p>Si desea restaurar una pieza, adjunte a su correo una fotografía general y detalles de las zonas que le preocupan.</p><p>Las medidas aproximadas, el material y cualquier información sobre su historia nos ayudarán a conocerla mejor.</p><p>Para consultar sobre una pintura de Antonio, indique el título de la obra.</p></aside></section>'

page('contacto','Contacto',contact,'contact')
archive_cards=[]
for i,p in enumerate(posts):
 if p.get('status')!='public-data-found':continue
 code=p['code'];date=datetime.datetime.fromtimestamp(p.get('timestamp',0),datetime.timezone.utc).strftime('%d.%m.%Y')
 caption=p.get('caption') or ''; first=next((x.strip() for x in caption.splitlines() if len(x.strip())>5),'Documento del estudio')
 title=first[:110]+('…' if len(first)>110 else '')
 matching=next((c for c in cases if code in c['ids']),None)
 visual=next((m for m in p.get('media',[]) if m.get('file') and m['type']=='image'),None)
 video=next((m for m in p.get('media',[]) if m.get('file') and m['type']=='video'),None)
 cover=img('restoration/'+visual['file'],title) if visual else img('restoration/'+video['file']+'.poster.jpg',title) if video else '<span class="video-card">Del taller.<br><em>En movimiento.</em><b>▷</b></span>'
 archive_cards.append(f'<a class="catalog-card archive-card" data-search="{esc(caption.lower())}" href="{BASE}archivo/{code}/"><div class="case-image">{cover}</div><div class="card-label"><small>{date}</small><h3>{esc(title)}</h3><span>Leer publicación <i>↗</i></span></div></a>')
 gallery=''
 for n,m in enumerate(p.get('media',[])):
  if not m.get('file'):continue
  src='restoration/'+m['file']
  visual=f'<video controls preload="metadata" playsinline poster="{BASE}assets/{src}.poster.jpg" src="{BASE}assets/{src}"></video>' if m['type']=='video' else f'<button class="zoom" data-full="{BASE}assets/{src}" data-caption="Documento {n+1} · {date}">{img(src,"Documento "+str(n+1)+" del estudio")}<span>Ampliar ↗</span></button>'
  gallery+=f'<figure>{visual}<figcaption>{n+1:02} / Archivo de la publicación · {date}</figcaption></figure>'
 more=f'<a class="action" href="{BASE}restauracion/{matching["slug"]}/">{{ VER EL PROYECTO }}</a>' if matching else ''
 body=f'<div class="breadcrumb"><a href="{BASE}archivo/">Archivo del estudio</a> / {date}</div><section class="object-layout archive-detail"><aside><span class="eyebrow">CUADERNO DEL ESTUDIO</span><h1>{esc(title)}</h1><p>Publicado el {date}</p>{more}<p class="aside-note">Texto y documentación originales de la publicación. Las imágenes pueden incluir referencias históricas además de las obras intervenidas.</p><a class="action" href="{p["url"]}">{{ VER EN INSTAGRAM ↗ }}</a></aside><div class="object-images"><div class="case-intro"><h2>Notas del taller</h2><div class="source-text">{esc(caption) if caption else "Esta publicación no incluye texto del estudio."}</div></div>{gallery}</div></section>'
 page('archivo/'+code,title,body,'rest')
